    if (m.indexOf(c.en_modified_prefix) === 0) {
      const name = (k.key_name && k.key_name.web) || k.key_name;
      hit.push({ key_id: k.key_id, name: name, created_at: k.created_at, en_modified: m, en: en.translation, tags: k.tags, is_new: String(k.created_at).indexOf(c.en_modified_prefix) === 0, has_tag: (k.tags || []).indexOf(c.tag) >= 0 });
    }
  }
}
const todo = hit.filter(function (k) { return !k.has_tag; });
const batch = c.mode === 'first' ? todo.slice(0, 1) : todo;
return [{ json: { total: total, seen: seen, en_modified_minutes_today: sameDay, matched: hit.length, new_count: hit.filter(function (k) { return k.is_new; }).length, to_tag: todo.length, keys: hit, body: { keys: batch.map(function (k) { return { key_id: k.key_id, tags: [c.tag], merge_tags: true }; }) } } }];

